test.each(['ADMIN','SUPERVISOR'])('actual App grants404 setup to %s and retires all four retained mutation callbacks after downgrade',async(role)=>{mockRoles=[role];let tree!:ReactTestRenderer;await act(async()=>{tree=create(renderApp())});try{await flush();const admin=tree.root.findByType(Admin),props=admin.props,retained=[props.createProduct,props.createEmployee,()=>props.saveTaxGroup({code:'B',name:'Tax',rate:'20.00'}),props.saveConfiguration];await act(async()=>{await admin.props.createProduct()});expect(mockWrites.some(x=>x.url.endsWith('/products')&&x.method==='POST')).toBe(true);mockWrites.length=0;mockRoles=['CASHIER'];mockToken+='-downgraded';await act(async()=>tree.update(renderApp()));await flush();expect(tree.root.findAllByType(Admin)).toHaveLength(0);await act(async()=>{for(const callback of retained)await callback()});expect(mockWrites).toHaveLength(0)}finally{await act(async()=>tree.unmount())}});
test('actual role hook retires retained callback through role ABA and unmount',()=>{let gate!:ReturnType<typeof useManagementAccess>;function Harness({roles}:{roles:string[]}){gate=useManagementAccess(true,roles);return null}let tree!:ReactTestRenderer;act(()=>{tree=create(<Harness roles={['ADMIN']}/>)});const retained=gate.guard();expect(retained()).toBe(true);act(()=>tree.update(<Harness roles={['CASHIER']}/>));expect(retained()).toBe(false);act(()=>tree.update(<Harness roles={['ADMIN']}/>));expect(retained()).toBe(false);const fresh=gate.guard();expect(fresh()).toBe(true);act(()=>tree.unmount());expect(fresh()).toBe(false)});

test('role authority can revoke a retained handler synchronously before React rerender',()=>{let gate!:ReturnType<typeof useManagementAccess>;function Harness(){gate=useManagementAccess(true,['ADMIN']);return null}let tree!:ReactTestRenderer;act(()=>{tree=create(<Harness/>)});const retained=gate.guard();expect(retained()).toBe(true);gate.synchronizeRoles(['AUDITOR']);expect(retained()).toBe(false);act(()=>tree.unmount());});

