test.each([false,true,'loss'])('actual pending permission response after auth transition cannot clear journal or publish old recovery, transition=%s',async(aba)=>{mockCart=true;sourceRecoveryFixture();mockRecoveryGrant.allowed_actions=['READ'];mockToken='RECOVERY_A';const held=deferredHTTP();let tree!:ReactTestRenderer;await act(async()=>{tree=create(renderApp())});try{await flush();const retained=tree.root.findByProps({testID:'reconcile-start'}).props.onPress;mockMutations.push({path:'/orders/order-1/recovery',method:'GET',promise:held.promise});let request!:Promise<any>;await act(async()=>{request=retained()});mockToken=aba==='loss'?'':'RECOVERY_B';await act(async()=>tree.update(renderApp()));await flush();if(aba===true){mockToken='RECOVERY_A';await act(async()=>tree.update(renderApp()));await flush()}mockRequests.length=0;await act(async()=>{held.resolve(httpOK(mockRecoveryGrant));await request});expect(mockRequests).toHaveLength(0);expect(mockJournalRemoved).toEqual([]);if(aba==='loss')expect(tree.root.findByProps({testID:'operator-login-email'})).toBeDefined();else expect(tree.root.findByProps({testID:'operation-unknown'})).toBeDefined();await act(async()=>retained());expect(mockRequests).toHaveLength(0);expect(mockJournalRemoved).toEqual([])}finally{await act(async()=>tree.unmount())}});

