test.each(['order_id','fiscal_sale_id'])('actual recovery rejects mismatched %s capability without financial POST or journal deletion',async(field)=>{mockCart=true;const durable=sourceRecoveryFixture(),frozen=JSON.stringify(durable);mockRecoveryGrant.allowed_actions=['READ'];mockRecoveryGrant[field]='foreign';let tree!:ReactTestRenderer;await act(async()=>{tree=create(renderApp())});try{await flush();mockRequests.length=0;await act(async()=>tree.root.findByProps({testID:'reconcile-start'}).props.onPress());expect(mockRequests).toHaveLength(2);expect(mockRequests[1].url.endsWith('/orders/order-1/recovery')).toBe(true);expect(mockRequests[0].method).toBe('GET');expect(mockJournalRemoved).toEqual([]);expect(JSON.stringify(durable)).toBe(frozen);expect(tree.root.findByProps({testID:'operation-unknown'})).toBeDefined()}finally{await act(async()=>tree.unmount())}});

 test.each([false,true])('closed source journal remains visible and read-only recoverable with another OPEN shift=%s',async(newOpen)=>{mockCart=true;sourceRecoveryFixture();mockShiftRows=[{id:'shift-1',employee_id:'operator',register_id:process.env.EXPO_PUBLIC_REGISTER_ID,state:'CLOSED',version:3},...(newOpen?[{id:'shift-2',employee_id:'operator',register_id:process.env.EXPO_PUBLIC_REGISTER_ID,state:'OPEN',version:1}]:[])];mockRecoveryGrant.allowed_actions=['READ'];let tree!:ReactTestRenderer;await act(async()=>{tree=create(renderApp())});try{await flush();expect(tree.root.findByProps({testID:'operation-unknown'})).toBeDefined();expect(tree.root.findByProps({testID:'shift-toggle'}).props.disabled).toBe(true);mockRequests.length=0;await act(async()=>tree.root.findByProps({testID:'shift-toggle'}).props.onPress());expect(mockRequests).toHaveLength(0);await act(async()=>tree.root.findByProps({testID:'reconcile-start'}).props.onPress());expect(mockRequests.map(x=>x.method)).toEqual(['GET','GET','GET','GET']);expect(mockJournalRemoved).toEqual(['order-1']);expect(tree.root.findAllByProps({testID:'operation-unknown'})).toHaveLength(0)}finally{await act(async()=>tree.unmount())}});

test('actual legacy quarantine export persists unresolved state and exposes no auth/proof or arbitrary discard',async()=>{mockCart=true;const durable:any=sourceRecoveryFixture();delete durable.source_order_id;durable.signed_intent.execution_authorization={payload:'PRIVATE_AUTH'};durable.signed_intent.client_proof={signature:'PRIVATE_PROOF'};let tree!:ReactTestRenderer;await act(async()=>{tree=create(renderApp())});try{await flush();expect(tree.root.findByProps({testID:'legacy-recovery-discover'})).toBeDefined();mockRequests.length=0;await act(async()=>tree.root.findByProps({testID:'legacy-recovery-discover'}).props.onPress());expect(mockLegacyRecords.get('order-1').status).toBe('QUARANTINED');expect(mockRequests).toHaveLength(0);await act(async()=>tree.root.findByProps({testID:'legacy-recovery-export'}).props.onPress());const report=tree.root.findByProps({testID:'legacy-recovery-report'}).props.children;expect(report).toContain('MINIPOS_LEGACY_RECOVERY_QUARANTINE');expect(report).not.toContain('PRIVATE_AUTH');expect(report).not.toContain('PRIVATE_PROOF');expect(report).not.toContain('2.50');expect(report).not.toContain('recovery-op');expect(report).not.toContain('recovery-receipt');expect(mockJournalEntries).toHaveLength(1);expect(mockJournalRemoved).toEqual([]);expect(tree.root.findByProps({testID:'shift-toggle'}).props.disabled).toBe(true);expect(tree.root.findAllByProps({testID:'legacy-recovery-discard'})).toHaveLength(0)}finally{await act(async()=>tree.unmount())}});
test('actual explicit legacy discovery confirms unique signed source linkage GET-only and clears exact original journal',async()=>{mockCart=true;const durable:any=sourceRecoveryFixture();delete durable.source_order_id;Object.assign(durable.signed_intent,{intent_id:'recovery-op',receipt_session_id:'recovery-receipt',operator_code:'0001'});mockRecoveryGrant.allowed_actions=['READ'];let tree!:ReactTestRenderer;await act(async()=>{tree=create(renderApp())});try{await flush();mockMutations.push({path:'/orders?limit=100',method:'GET',promise:Promise.resolve(httpOK({items:[mockRecoveredOrder],page:{has_more:false}}))});const frozen=JSON.stringify(durable);mockRequests.length=0;await act(async()=>tree.root.findByProps({testID:'legacy-recovery-discover'}).props.onPress());expect(mockRequests.map(x=>x.method)).toEqual(['GET','GET','GET','GET','GET']);expect(mockJournalRemoved).toEqual(['order-1']);expect(mockLegacyRecords.get('order-1').status).toBe('LINKED');expect(JSON.stringify(durable)).toBe(frozen);expect(tree.root.findAllByProps({testID:'operation-unknown'})).toHaveLength(0)}finally{await act(async()=>tree.unmount())}});

test.each(['auth','config','operator','operator-ABA'])('actual delayed legacy export and retained callback cannot cross committed %s scope',async(change)=>{mockRoles=['ADMIN'];const durable:any=sourceRecoveryFixture();delete durable.source_order_id;Object.assign(durable.signed_intent,{intent_id:'recovery-op',receipt_session_id:'recovery-receipt',operator_code:'0001'});let tree!:ReactTestRenderer;await act(async()=>{tree=create(renderApp())});try{await flush();const retained=tree.root.findByProps({testID:'legacy-recovery-export'}).props.onPress;await act(async()=>retained());expect(tree.root.findByProps({testID:'legacy-recovery-report'}).props.children).toContain('2.50');const held=deferredHTTP();mockJournalLoadQueue.push(held.promise);let pending!:Promise<void>;await act(async()=>{pending=retained()});if(change==='auth'){mockToken='NEW_EXPORT_AUTH';await act(async()=>tree.update(renderApp()));await flush();}else if(change==='config'){const cfg={id:'replacement-config',version:2,location_name:'Replacement',fiscal_register_id:'00000000-0000-4000-8000-000000000099'};mockMutations.push({path:'/configuration',method:'PATCH',promise:Promise.resolve(httpOK(cfg))});mockConfigurationQueue.push(Promise.resolve(httpOK(cfg)));await act(async()=>tree.root.findByType(Admin).props.saveConfiguration());await flush();}else{mockSessionQueue.push(Promise.resolve(httpOK({authenticated:true,employee:{id:'another-employee',first_name:'Other',last_name:'Operator',operator_code:'0002',roles:['ADMIN']}})));await act(async()=>tree.root.findByType(Admin).props.createProduct());await flush();if(change==='operator-ABA'){mockSessionQueue.push(Promise.resolve(httpOK({authenticated:true,employee:{id:'operator',first_name:'Test',last_name:'Person',operator_code:'0001',roles:['ADMIN']}})));await act(async()=>tree.root.findByType(Admin).props.createProduct());await flush();}}expect(tree.root.findAllByProps({testID:'legacy-recovery-report'})).toHaveLength(0);await act(async()=>{held.resolve(durable);await pending});expect(tree.root.findAllByProps({testID:'legacy-recovery-report'})).toHaveLength(0);await act(async()=>retained());expect(tree.root.findAllByProps({testID:'legacy-recovery-report'})).toHaveLength(0);expect(mockJournalRemoved).toEqual([])}finally{await act(async()=>tree.unmount())}});
